use horus::prelude::*;

/// Robot physical parameters
const WHEEL_BASE: f32 = 0.3;    // meters between wheels
const WHEEL_RADIUS: f32 = 0.05; // meters
const MAX_RPM: f32 = 200.0;     // safety limit

/// Motor output for a single wheel
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct WheelCmd {
    left_rpm: f32,
    right_rpm: f32,
}

// ── Drive Node ──────────────────────────────────────────────

struct DriveNode {
    cmd_sub: Topic<CmdVel>,
    wheel_pub: Topic<WheelCmd>,
    last_cmd: CmdVel,
}

impl DriveNode {
    fn new() -> Result<Self> {
        Ok(Self {
            cmd_sub: Topic::new("cmd_vel")?,
            wheel_pub: Topic::new("wheel.cmd")?,
            last_cmd: CmdVel::default(),
        })
    }
}

impl Node for DriveNode {
    fn name(&self) -> &str { "Drive" }

    fn tick(&mut self) {
        // IMPORTANT: always recv() every tick to drain the buffer
        if let Some(cmd) = self.cmd_sub.recv() {
            self.last_cmd = cmd;
        }

        // Differential drive kinematics: convert (linear, angular) to (left, right)
        let v = self.last_cmd.linear;
        let w = self.last_cmd.angular;
        let left = (v - w * WHEEL_BASE / 2.0) / WHEEL_RADIUS;
        let right = (v + w * WHEEL_BASE / 2.0) / WHEEL_RADIUS;

        // Convert rad/s to RPM and clamp to safety limit
        let to_rpm = 60.0 / (2.0 * std::f32::consts::PI);
        let left_rpm = (left * to_rpm).clamp(-MAX_RPM, MAX_RPM);
        let right_rpm = (right * to_rpm).clamp(-MAX_RPM, MAX_RPM);

        self.wheel_pub.send(WheelCmd { left_rpm, right_rpm });
    }

    fn shutdown(&mut self) -> Result<()> {
        // SAFETY: zero both motors before exiting — prevents runaway
        self.wheel_pub.send(WheelCmd { left_rpm: 0.0, right_rpm: 0.0 });
        Ok(())
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();

    // Execution order: DriveNode reads cmd_vel and publishes wheel commands
    scheduler.add(DriveNode::new()?)
        .order(0)              // only node, runs first
        .rate(50_u64.hz())     // 50Hz control loop — auto-enables RT
        .on_miss(Miss::Warn)   // log if tick overruns
        .build()?;

    scheduler.run()
}

use horus::prelude::*;

/// E-stop trigger from hardware or software
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct EStopSignal {
    triggered: u8,   // 0 = clear, 1 = triggered (u8 for repr(C) compat)
    source: u8,      // 0 = hardware, 1 = software, 2 = remote
}

/// Status published by the E-stop monitor
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct SafetyStatus {
    estop_active: u8,
    consecutive_clears: u32,
    uptime_ticks: u64,
}

// ── E-Stop Monitor ──────────────────────────────────────────

struct EStopNode {
    estop_sub: Topic<EStopSignal>,
    cmd_pub: Topic<CmdVel>,
    status_pub: Topic<SafetyStatus>,
    estop_active: bool,
    consecutive_clears: u32,
    ticks: u64,
}

impl EStopNode {
    fn new() -> Result<Self> {
        Ok(Self {
            estop_sub: Topic::new("safety.estop")?,
            cmd_pub: Topic::new("cmd_vel")?,
            status_pub: Topic::new("safety.status")?,
            estop_active: false,
            consecutive_clears: 0,
            ticks: 0,
        })
    }
}

impl Node for EStopNode {
    fn name(&self) -> &str { "EStop" }

    fn tick(&mut self) {
        self.ticks += 1;

        // IMPORTANT: always recv() every tick
        if let Some(signal) = self.estop_sub.recv() {
            if signal.triggered != 0 {
                // SAFETY: immediately stop all motion
                self.estop_active = true;
                self.consecutive_clears = 0;
            } else {
                self.consecutive_clears += 1;
            }
        } else {
            // WARNING: no signal received — treat as potential fault
            // In safety-critical systems, loss of heartbeat = stop
            self.consecutive_clears = 0;
        }

        // Require N consecutive clear signals before releasing E-stop
        const CLEAR_THRESHOLD: u32 = 50; // 50 ticks at 100Hz = 0.5 seconds
        if self.estop_active && self.consecutive_clears >= CLEAR_THRESHOLD {
            self.estop_active = false;
        }

        if self.estop_active {
            // SAFETY: override cmd_vel with zero — stops all motion
            self.cmd_pub.send(CmdVel { linear: 0.0, angular: 0.0 });
        }

        self.status_pub.send(SafetyStatus {
            estop_active: self.estop_active as u8,
            consecutive_clears: self.consecutive_clears,
            uptime_ticks: self.ticks,
        });
    }

    fn shutdown(&mut self) -> Result<()> {
        // SAFETY: zero velocity on shutdown
        self.cmd_pub.send(CmdVel { linear: 0.0, angular: 0.0 });
        Ok(())
    }

    fn enter_safe_state(&mut self) {
        // Called by scheduler if this node misses its deadline
        self.estop_active = true;
        self.cmd_pub.send(CmdVel { linear: 0.0, angular: 0.0 });
    }

    fn is_safe_state(&self) -> bool {
        self.estop_active
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();

    // Execution order: E-stop runs LAST — overrides any cmd_vel from other nodes
    scheduler.add(EStopNode::new()?)
        .order(100)                // high order = runs after drive/planner nodes
        .rate(100_u64.hz())        // 100Hz safety monitoring — auto-enables RT
        .budget(200.us())          // tight budget for safety-critical code
        .deadline(500.us())        // tight deadline
        .on_miss(Miss::SafeMode)   // CRITICAL: if this node misses, force safe state
        .max_deadline_misses(0)    // zero tolerance for misses
        .build()?;

    scheduler.run()
}

use horus::prelude::*;

/// Simplified orientation from integrated gyro
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct Orientation {
    roll: f32,
    pitch: f32,
    yaw: f32,
    timestamp_ns: u64,
}

// ── IMU Node ────────────────────────────────────────────────

struct ImuNode {
    imu_pub: Topic<Imu>,
    orientation_pub: Topic<Orientation>,
    roll: f32,
    pitch: f32,
    yaw: f32,
    tick_count: u64,
}

impl ImuNode {
    fn new() -> Result<Self> {
        Ok(Self {
            imu_pub: Topic::new("imu.raw")?,
            orientation_pub: Topic::new("imu.orientation")?,
            roll: 0.0,
            pitch: 0.0,
            yaw: 0.0,
            tick_count: 0,
        })
    }

    /// Simulate IMU hardware read (replace with real driver)
    fn read_hardware(&self) -> Imu {
        Imu {
            orientation: [1.0, 0.0, 0.0, 0.0],  // identity quaternion (w,x,y,z)
            angular_velocity: [0.01, 0.0, 0.05],  // rad/s (roll, pitch, yaw)
            linear_acceleration: [0.0, 0.0, 9.81], // m/s² (x, y, z)
        }
    }
}

impl Node for ImuNode {
    fn name(&self) -> &str { "ImuReader" }

    fn tick(&mut self) {
        let imu = self.read_hardware();

        // Publish raw IMU for any subscriber
        self.imu_pub.send(imu);

        // Simple gyro integration (replace with Madgwick/Mahony in production)
        let dt = 1.0 / 100.0; // 100Hz
        self.roll += imu.angular_velocity[0] as f32 * dt;
        self.pitch += imu.angular_velocity[1] as f32 * dt;
        self.yaw += imu.angular_velocity[2] as f32 * dt;

        self.tick_count += 1;

        self.orientation_pub.send(Orientation {
            roll: self.roll,
            pitch: self.pitch,
            yaw: self.yaw,
            timestamp_ns: self.tick_count * 10_000_000, // 10ms per tick
        });
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();

    // Execution order: IMU reads hardware and publishes
    scheduler.add(ImuNode::new()?)
        .order(0)
        .rate(100_u64.hz())    // 100Hz sensor rate — auto-enables RT
        .build()?;

    scheduler.run()
}

use horus::prelude::*;

/// Safety zones (meters)
const STOP_DISTANCE: f32 = 0.3;    // emergency stop
const SLOW_DISTANCE: f32 = 0.8;    // reduce speed
const CRUISE_SPEED: f32 = 0.5;     // m/s forward
const TURN_SPEED: f32 = 0.8;       // rad/s turning

// ── Avoidance Node ──────────────────────────────────────────

struct AvoidanceNode {
    scan_sub: Topic<LaserScan>,
    cmd_pub: Topic<CmdVel>,
}

impl AvoidanceNode {
    fn new() -> Result<Self> {
        Ok(Self {
            scan_sub: Topic::new("lidar.scan")?,
            cmd_pub: Topic::new("cmd_vel")?,
        })
    }

    /// Find minimum range in a slice of the scan
    fn min_range(ranges: &[f32], start: usize, end: usize) -> f32 {
        ranges[start..end]
            .iter()
            .copied()
            .filter(|r| r.is_finite() && *r > 0.01)
            .fold(f32::MAX, f32::min)
    }
}

impl Node for AvoidanceNode {
    fn name(&self) -> &str { "Avoidance" }

    fn tick(&mut self) {
        // IMPORTANT: always recv() every tick to drain the buffer
        let scan = match self.scan_sub.recv() {
            Some(s) => s,
            None => return, // no data yet — skip this tick
        };

        let n = scan.ranges.len();
        if n == 0 { return; }

        // Split scan into three zones: left (0..n/3), center (n/3..2n/3), right (2n/3..n)
        let third = n / 3;
        let left_min = Self::min_range(&scan.ranges, 0, third);
        let center_min = Self::min_range(&scan.ranges, third, 2 * third);
        let right_min = Self::min_range(&scan.ranges, 2 * third, n);

        // Reactive behavior
        let cmd = if center_min < STOP_DISTANCE {
            // WARNING: obstacle dead ahead — emergency stop
            CmdVel { linear: 0.0, angular: 0.0 }
        } else if center_min < SLOW_DISTANCE {
            // Obstacle ahead — turn toward the more open side
            let angular = if left_min > right_min { TURN_SPEED } else { -TURN_SPEED };
            CmdVel { linear: 0.1, angular }
        } else if left_min < SLOW_DISTANCE {
            // Obstacle on left — veer right
            CmdVel { linear: CRUISE_SPEED * 0.7, angular: -TURN_SPEED * 0.5 }
        } else if right_min < SLOW_DISTANCE {
            // Obstacle on right — veer left
            CmdVel { linear: CRUISE_SPEED * 0.7, angular: TURN_SPEED * 0.5 }
        } else {
            // Clear — cruise forward
            CmdVel { linear: CRUISE_SPEED, angular: 0.0 }
        };

        self.cmd_pub.send(cmd);
    }

    fn shutdown(&mut self) -> Result<()> {
        // SAFETY: stop the robot on exit
        self.cmd_pub.send(CmdVel { linear: 0.0, angular: 0.0 });
        Ok(())
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();

    // Execution order: reads lidar scan, publishes velocity
    scheduler.add(AvoidanceNode::new()?)
        .order(0)
        .rate(20_u64.hz())     // 20Hz — match typical LiDAR rate
        .on_miss(Miss::Warn)
        .build()?;

    scheduler.run()
}

use horus::prelude::*;

/// Wheel odometry: position from encoder counts
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct WheelOdom {
    x: f32,
    y: f32,
    theta: f32,
    speed: f32,
}

/// IMU-derived heading
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct ImuHeading {
    yaw: f32,
    yaw_rate: f32,
}

/// Fused state estimate
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct FusedPose {
    x: f32,
    y: f32,
    theta: f32,
    speed: f32,
    confidence: f32,
}

// ── Fusion Node ─────────────────────────────────────────────

struct FusionNode {
    odom_sub: Topic<WheelOdom>,
    imu_sub: Topic<ImuHeading>,
    pose_pub: Topic<FusedPose>,
    last_odom: Option<WheelOdom>,
    last_imu: Option<ImuHeading>,
    alpha: f32,
}

impl FusionNode {
    fn new() -> Result<Self> {
        Ok(Self {
            odom_sub: Topic::new("odom.wheels")?,
            imu_sub: Topic::new("imu.heading")?,
            pose_pub: Topic::new("pose.fused")?,
            last_odom: None,
            last_imu: None,
            alpha: 0.7, // favor IMU for heading (less drift than wheels on turns)
        })
    }
}

impl Node for FusionNode {
    fn name(&self) -> &str { "Fusion" }

    fn tick(&mut self) {
        // IMPORTANT: always recv() ALL topics every tick to drain buffers
        if let Some(odom) = self.odom_sub.recv() {
            self.last_odom = Some(odom);
        }
        if let Some(imu) = self.imu_sub.recv() {
            self.last_imu = Some(imu);
        }

        // Fuse only when both sources are available
        let (odom, imu) = match (&self.last_odom, &self.last_imu) {
            (Some(o), Some(i)) => (o, i),
            _ => return,
        };

        // Complementary filter: blend odom heading with IMU heading
        let fused_theta = (1.0 - self.alpha) * odom.theta + self.alpha * imu.yaw;

        let confidence = if imu.yaw_rate.abs() > 0.5 { 0.6 } else { 0.9 };

        self.pose_pub.send(FusedPose {
            x: odom.x,
            y: odom.y,
            theta: fused_theta,
            speed: odom.speed,
            confidence,
        });
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();

    // Execution order: fusion reads both sensors and publishes fused pose
    scheduler.add(FusionNode::new()?)
        .order(0)
        .rate(50_u64.hz())
        .build()?;

    scheduler.run()
}

use horus::prelude::*;

/// Setpoint command: what we want
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct Setpoint {
    target: f32,
}

/// Measured feedback: what we have
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct Measurement {
    value: f32,
}

/// PID output: what to do
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct ControlOutput {
    command: f32,
    error: f32,
    p_term: f32,
    i_term: f32,
    d_term: f32,
}

// ── PID Node ────────────────────────────────────────────────

struct PidNode {
    setpoint_sub: Topic<Setpoint>,
    measurement_sub: Topic<Measurement>,
    output_pub: Topic<ControlOutput>,
    // PID gains
    kp: f32,
    ki: f32,
    kd: f32,
    // State
    integral: f32,
    prev_error: f32,
    prev_derivative: f32,
    // Limits
    output_min: f32,
    output_max: f32,
    integral_max: f32,
    // Derivative filter coefficient (0.0 = no filter, 0.9 = heavy filter)
    alpha: f32,
    // Cached inputs
    target: f32,
    measured: f32,
}

impl PidNode {
    fn new(kp: f32, ki: f32, kd: f32) -> Result<Self> {
        Ok(Self {
            setpoint_sub: Topic::new("pid.setpoint")?,
            measurement_sub: Topic::new("pid.measurement")?,
            output_pub: Topic::new("pid.output")?,
            kp, ki, kd,
            integral: 0.0,
            prev_error: 0.0,
            prev_derivative: 0.0,
            output_min: -1.0,
            output_max: 1.0,
            integral_max: 0.5,   // anti-windup limit
            alpha: 0.8,          // derivative low-pass filter
            target: 0.0,
            measured: 0.0,
        })
    }
}

impl Node for PidNode {
    fn name(&self) -> &str { "PID" }

    fn tick(&mut self) {
        // IMPORTANT: always recv() every tick to drain buffers
        if let Some(sp) = self.setpoint_sub.recv() {
            self.target = sp.target;
        }
        if let Some(m) = self.measurement_sub.recv() {
            self.measured = m.value;
        }

        let dt = 1.0 / 200.0; // 200Hz control rate
        let error = self.target - self.measured;

        // P term
        let p_term = self.kp * error;

        // I term with anti-windup clamping
        self.integral += error * dt;
        self.integral = self.integral.clamp(-self.integral_max, self.integral_max);
        let i_term = self.ki * self.integral;

        // D term with low-pass filter to reduce noise
        let raw_derivative = (error - self.prev_error) / dt;
        let filtered = self.alpha * self.prev_derivative + (1.0 - self.alpha) * raw_derivative;
        let d_term = self.kd * filtered;
        self.prev_derivative = filtered;
        self.prev_error = error;

        // Total output with saturation
        let command = (p_term + i_term + d_term).clamp(self.output_min, self.output_max);

        self.output_pub.send(ControlOutput {
            command,
            error,
            p_term,
            i_term,
            d_term,
        });
    }

    fn shutdown(&mut self) -> Result<()> {
        // SAFETY: zero the control output on shutdown
        self.output_pub.send(ControlOutput::default());
        Ok(())
    }
}

fn main() -> Result<()> {
    let mut scheduler = Scheduler::new();

    // PID gains: tune for your plant
    // Execution order: PID reads setpoint + measurement, publishes output
    scheduler.add(PidNode::new(2.0, 0.5, 0.1)?)
        .order(0)
        .rate(200_u64.hz())       // 200Hz control loop — auto-enables RT
        .budget(400.us())         // 400μs budget (tight for control)
        .on_miss(Miss::Warn)
        .build()?;

    scheduler.run()
}

use horus::prelude::*;

/// Lightweight bridge payload — serialized for cross-framework transport
#[derive(Debug, Clone, Copy, Default)]
#[repr(C)]
struct BridgePacket {
    topic_id: u32,       // which topic this came from
    timestamp_ns: u64,
    linear: f32,         // for cmd_vel
    angular: f32,
}

// ── Bridge Node ─────────────────────────────────────────────

struct BridgeOutNode {
    cmd_sub: Topic<CmdVel>,
    imu_sub: Topic<Imu>,
    bridge_pub: Topic<BridgePacket>,
    tick_count: u64,
}

impl BridgeOutNode {
    fn new() -> Result<Self> {
        Ok(Self {
            cmd_sub: Topic::new("cmd_vel")?,
            imu_sub: Topic::new("imu.raw")?,
            bridge_pub: Topic::new("bridge.out")?,
            tick_count: 0,
        })
    }
}

impl Node for BridgeOutNode {
    fn name(&self) -> &str { "BridgeOut" }

    fn tick(&mut self) {
        self.tick_count += 1;

        // IMPORTANT: always recv() every tick to drain buffers
        if let Some(cmd) = self.cmd_sub.recv() {
            self.bridge_pub.send(BridgePacket {
                topic_id: 1, // cmd_vel
                timestamp_ns: self.tick_count * 20_000_000, // 50Hz
