                hlog!(info, "Received {} points, centroid: ({:.2}, {:.2}, {:.2})",
                    points.len(),
                    centroid[0] / n, centroid[1] / n, centroid[2] / n);
            }
        }
    }

    fn shutdown(&mut self) -> Result<()> {
        hlog!(info, "PointCloud receiver stopped");
        Ok(())
    }
}

